if(type=='novel'){
  d.text||'';
}else if(type=='comic'){
  var imgs=(d.data||{}).originalImages||[];
  imgs.map(function(u){return '<img src="'+getFileUrl(u)+'">'}).join('<br>');
}else if(type=='audio'){
  var audioUrl=(d.data||{}).url||'';
  if(audioUrl.startsWith('/'))audioUrl=getFileUrl(audioUrl);
  audioUrl;
}else if(type=='video'){
  var b=d.data||{};
  if(b.model)b=b.model;
  var videoUrl=b.url||'';
  if(videoUrl.startsWith('/'))videoUrl=getFileUrl(videoUrl);
  var opts={headers:{'Referer':'https://www.uaa.com'}};
  try{
    if(book.durChapterIndex==chapter.index){
      java.toast('正在加载视频…');
      java.openVideoPlayer(videoUrl+','+JSON.stringify(opts),'视频播放器',false);
    }
  }catch(e){}
  '🎬 点击刷新播放视频\n视频链接：'+videoUrl;
}else{result;}

