ruleContent.content:
@js:(function() {
    // 获取网页源码
    var html = src || '';
    var num = null, pasd = null;

    // 提取图片数量 num
    var numMatch = html.match(/var num\s*=\s*eval\s*\(\s*["']?(\d+)["']?\s*\)/);
    // 提取图片基础路径 pasd
    var pasdMatch = html.match(/var pasd\s*=\s*"([^"]+)"/);

    if (numMatch) num = parseInt(numMatch[1], 10);
    if (pasdMatch) pasd = pasdMatch[1];

    if (!num || !pasd) {
        return '提取失败：未找到图片信息';
    }

    // 生成所有 <img> 标签
    var imgTags = [];
